class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

# 创建一个循环链表类
class CircularLinkedList:
    def __init__(self):
        self.head = None

    def is_empty(self):
        return  self.head is None

    def traverse_list(self):
        if self.is_empty():
            print('空链表')
            return
        current = self.head
        while current.next is not self.head:
            print(f"{current.data} ->", end=" ")
            current = current.next
        print(f"{current.data} -> {self.head.data}")

    def node_count(self):
        if self.is_empty():
            return 0
        count = 1
        current = self.head
        while current.next is not self.head:
            count += 1
            current = current.next
        return count

    def append_into_empty(self, data):
        new_node = Node(data)
        self.head = new_node
        new_node.next = self.head

    def append(self, data):
        if self.is_empty():
            self.append_into_empty(data)
            return
        new_node = Node(data)
        current = self.head
        while current.next != self.head:
            current = current.next
        current.next = new_node
        new_node.next = self.head


    def insert_at_beginning(self, data):
        if self.is_empty():  
            self.append_into_empty(data)
            return      
        new_node = Node(data)
        current = self.head
        while current.next != self.head:
            current = current.next
        current.next = new_node
        new_node.next = self.head
        self.head = new_node

    def insert_at_position(self, data, position):
        if position <= 0 or position > self.node_count():
            print("无效的位置")
            return
        elif position == 1:
            self.insert_at_beginning(data)
            return
        elif position == self.node_count():
            self.append(data)
            return
        else:
            new_node = Node(data)
            current = self.head
            for i in range(1, position-1):
                current = current.next
            new_node.next = current.next
            current.next = new_node
    # 从开始删除
    def delete_from_beginning(self):
        if self.is_empty():
            print('无法从空链表中删除')
        elif self.node_count() == 1:
            temp = self.head
            self.head = None
            del temp
        else:
            temp = self.head
            current = self.head
            while current.next is not self.head:
                current = current.next
            self.head = self.head.next
            current.next = self.head
            del temp

    def delete_at_position(self, position):
        if self.is_empty():
            print('无法从空的循环链表中删除')
        elif position <= 0 or position > self.node_count():
            print('无效的位置')
        elif position == 1:
            self.delete_from_beginning()
        else:
            current = self.head
            prev_node = None
            for i in range(1, position):
                prev_node = current
                current = current.next
            prev_node.next = current.next
            del current

    # 反转方法
    def reverse(self):
        # 如果元素为0或1，无需反转
        if self.node_count() < 2:
            return

        # 定义3个指针
        prev = None
        current = self.head
        next_node = current.next

        while True:

            # 将当前节点的下一个指针指向前一个节点
            current.next = prev

            # 滑动指针
            prev = current
            current = next_node
            next_node = current.next

            # 重复直到你再次到达头部
            if current == self.head:
                break

        # 调整头部
        self.head.next = prev
        self.head = prev


